struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

// Requires: 2 texture images (add via Textures panel, slots 0 and 1)
// Slot 0: [[vk::combinedImageSampler]] [[vk::binding(0, 1)]]
// Slot 1: [[vk::combinedImageSampler]] [[vk::binding(1, 1)]]

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

[[vk::combinedImageSampler]] [[vk::binding(0, 1)]]
Texture2D tex0 : register(t0);
[[vk::combinedImageSampler]] [[vk::binding(0, 1)]]
SamplerState samp0 : register(s0);

[[vk::combinedImageSampler]] [[vk::binding(1, 1)]]
Texture2D tex1 : register(t1);
[[vk::combinedImageSampler]] [[vk::binding(1, 1)]]
SamplerState samp1 : register(s1);

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001;
    float blend = 0.5 + 0.5 * sin(t);
    float4 a = tex0.Sample(samp0, i.uv);
    float4 b = tex1.Sample(samp1, i.uv);
    return lerp(a, b, blend);
}
